      "verdict": "supported",
      "reason": "Every admitted moped combination satisfies ru.trailer_or_combination's combination branch, while the moped contract alone establishes no coupling."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Every admitted motor-vehicle combination satisfies ru.trailer_or_combination's combination branch, while self-propulsion alone establishes no coupling."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Every admitted motorcycle combination satisfies ru.trailer_or_combination's combination branch, while the motorcycle contract alone establishes no coupling."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Every admitted official-vehicle combination satisfies ru.trailer_or_combination's combination branch, while official service or identifying equipment alone establishes no coupling."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than the transporting device, so the admitting words reach no member as a combination of vehicles."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "A pedestrian carrying a cane or receiving guidance remains a person, not two or more vehicles coupled together."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The exception requires exclusive use upon stationary rails, whereas the contract's description of on-track equipment does not establish that exclusivity."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "Every admitted school-bus combination satisfies ru.trailer_or_combination's combination branch, while school designation and markings alone establish no coupling."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Every admitted taxicab combination satisfies ru.trailer_or_combination's combination branch, while passenger-for-hire status and markings alone establish no coupling."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Every admitted tour-bus or limousine combination satisfies ru.trailer_or_combination's combination branch, while the service and livery contract alone establishes no coupling."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract also admits an individual drawn vehicle, which is not itself necessarily the required coupled collection of two or more qualifying vehicles."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Every admitted transit-bus combination satisfies ru.trailer_or_combination's combination branch, while transit service and identifying displays alone establish no coupling."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "Every admitted truck combination satisfies ru.trailer_or_combination's combination branch, while a goods-carrying body alone establishes no coupling."
    }
  ]
}

